  w.autopay("M1005", "새싹수학학원", 320000, 12, "09:00");

  const plan = w.plan("2026-10-12");
  eq([plan.planned, plan.scheduled], [5, 5], "reminders planned for the 12th");

  // 08:00 출금이 잔액 부족으로 실패 → 2시간 뒤 재출금, 그 30분 전에 안내
