import { addMinutes, fromEpochSeconds, LocalDateTime, toEpochSeconds } from "../time/localTime";
import { QuietHours } from "./quietHours";

/**
 * pushq 2.8.0 은 예약 시각이 5분 경계(분 % 5 == 0, 초 00)가 아니면 티켓만 주고 큐에 넣지 않는다.
 * (2.3.x 의 10분 경계와 다르니 벤더 버전이 바뀌면 여기부터 다시 확인한다.)
 */
const PUSHQ_SLOT_SECONDS = 5 * 60;

/** 직전 경계로 내린다 — 고객 설정 시점보다 늦게 나가지 않도록 */
export function floorToPushqSlot(t: LocalDateTime): LocalDateTime {
  const sec = toEpochSeconds(t);
  return fromEpochSeconds(sec - (sec % PUSHQ_SLOT_SECONDS));
}

/**
 * 알림 발송 시각 정책.
 * - 안내 대상 시각(출금·재출금)보다 lead 분 앞서 보낸다.
 * - 야간 방해 금지 구간에 걸리면 전날 저녁으로 당긴다.
 * - 푸시 예약 경계에 맞춰 직전 경계로 내린다.
 * 결과는 그대로 푸시 예약 시각이 된다.
 */
export class SendTimePolicy {
  constructor(private readonly quiet: QuietHours) {}

  sendAt(dueAt: LocalDateTime, leadMinutes: number): LocalDateTime {
    const nominal = addMinutes(dueAt, -leadMinutes);
    return floorToPushqSlot(this.quiet.pullBack(nominal));
  }
}

